import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    p = 1
    by_name = {}
    by_num = {}
    out = []
    for _ in range(n):
        op = data[p]
        if op == 'ADD':
            name, num = data[p + 1], data[p + 2]
            p += 3
            if name in by_name:
                del by_num[by_name.pop(name)]
            if num in by_num:
                del by_name[by_num.pop(num)]
            by_name[name] = num
            by_num[num] = name
        elif op == 'NAME':
            out.append(by_num.get(data[p + 1], 'NONE'))
            p += 2
        else:
            out.append(by_name.get(data[p + 1], 'NONE'))
            p += 2
    print('\n'.join(out))

